#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_dpi_pair.sh: the gate decides which of the two DPI
# helper spellings is current, so its four combinations are contract — the
# stand-in pair complete, the stand-in pair broken, the merged form with the
# pair retired, and the merged form still dragging the pair along. Each case
# builds a throwaway repository so the answer never depends on which side of
# the #962 merge a checkout happens to sit on.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_dpi_pair.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-dpi-pair-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

failures=0
check() { # name want-cmd got-cmd
    local name=$1 want=$2 got=$3
    if [ "$want" = "$got" ]; then
        printf 'ok    %s (rc %s)\n' "$name" "$got"
    else
        printf 'FAIL  %s: want rc %s, got rc %s\n' "$name" "$want" "$got"
        failures=$((failures + 1))
    fi
}

new_repo() { # name — git init + identity, echoes the path
    local dir="$SANDBOX/$1"
    mkdir -p "$dir/PIMETextService" "$dir/tests" || return 1
    ( cd "$dir" && git init -q . \
        && git -c core.autocrlf=false config core.autocrlf false ) >/dev/null 2>&1 || return 1
    printf '%s' "$dir"
}

run_gate() { # dir
    ( cd "$1" && bash "$GATE" ) >/dev/null 2>&1
    printf '%s' "$?"
}

# 1. The stand-in pair while #962 is unmerged.
d=$(new_repo standin) || { echo "self-test: sandbox init failed" >&2; exit 2; }
printf '#include "DpiUtils.h"\nint TextService::candFontHeight(HWND h) { return candFontHeightImpl(h); }\n' \
    >"$d/PIMETextService/PIMETextService.cpp"
printf '#pragma once\n' >"$d/PIMETextService/DpiUtils.h"
printf 'int main() { return 0; }\n' >"$d/tests/dpi_helper_test.cpp"
check "stand-in pair complete" 0 "$(run_gate "$d")"

# 2. The stand-in half-lands: the header is gone, the test still builds.
rm -f "$d/PIMETextService/DpiUtils.h"
check "stand-in pair missing its header" 1 "$(run_gate "$d")"

# 3. #962 merged and the pair retired.
d2=$(new_repo merged) || { echo "self-test: sandbox init failed" >&2; exit 2; }
printf 'static UINT getWindowDpi(HWND hwnd) { return 96; }\n' >"$d2/PIMETextService/PIMETextService.cpp"
check "merged form, pair retired" 0 "$(run_gate "$d2")"

# 4. #962 merged but the orphaned pair still ships beside it.
printf '#pragma once\n' >"$d2/PIMETextService/DpiUtils.h"
check "merged form with the orphan left behind" 1 "$(run_gate "$d2")"

# 5. No product tree at all: a docs-only worktree is not the gate's business.
mkdir -p "$SANDBOX/plain"
( cd "$SANDBOX/plain" && git init -q . ) >/dev/null 2>&1
check "no PIMETextService tree" 125 "$(run_gate "$SANDBOX/plain")"

# 6. Outside a repository: not applicable.
check "outside a repo" 125 "$( cd "$SANDBOX" && bash "$GATE" >/dev/null 2>&1; printf '%s' "$?" )"

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
